import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose1d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose1d_kernel(const float* input,
                                        const float* weight,
                                        const float* bias,
                                        float* output,
                                        int N,
                                        int C_in,
                                        int L_in,
                                        int C_out,
                                        int K,
                                        int stride,
                                        int padding,
                                        int output_padding,
                                        int groups,
                                        bool has_bias) 
{
    // Compute the length of the output signal
    int L_out = (L_in - 1) * stride - 2 * padding + K + output_padding;
    int total_threads = N * C_out * L_out;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_threads) return;

    int n = idx / (C_out * L_out);
    int r = idx % (C_out * L_out);
    int co = r / L_out;
    int xo = r % L_out;

    float val = 0.0f;
    // Naive computation of transposed 1D convolution
    for (int ci = 0; ci < C_in; ci++) {
        for (int k = 0; k < K; k++) {
            int xi = (xo + padding - k) / stride;
            int remainder = (xo + padding - k) % stride;
            if (xi >= 0 && xi < L_in && remainder == 0) {
                int w_idx = ci * C_out * K + co * K + k;
                int i_idx = n * C_in * L_in + ci * L_in + xi;
                val += input[i_idx] * weight[w_idx];
            }
        }
    }
    if (has_bias) {
        val += bias[co];
    }
    output[idx] = val;
}

torch::Tensor conv_transpose1d_cuda(torch::Tensor x,
                                    torch::Tensor weight,
                                    torch::Tensor bias,
                                    int stride,
                                    int padding,
                                    int output_padding,
                                    int groups,
                                    bool has_bias) 
{
    const auto N = x.size(0);
    const auto C_in = x.size(1);
    const auto L_in = x.size(2);
    const auto C_out = weight.size(1);
    const auto K = weight.size(2);
    int L_out = (L_in - 1) * stride - 2 * padding + K + output_padding;

    auto out_options = x.options();
    auto out = torch::zeros({N, C_out, L_out}, out_options);

    int total_threads = N * C_out * L_out;
    int threads = 256;
    int blocks = (total_threads + threads - 1) / threads;

    conv_transpose1d_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        out.data_ptr<float>(),
        N,
        C_in,
        L_in,
        C_out,
        K,
        stride,
        padding,
        output_padding,
        groups,
        has_bias
    );
    return out;
}
""";

conv_transpose1d_cpp_source = r"""
torch::Tensor conv_transpose1d_cuda(torch::Tensor x,
                                    torch::Tensor weight,
                                    torch::Tensor bias,
                                    int stride,
                                    int padding,
                                    int output_padding,
                                    int groups,
                                    bool has_bias);
""";

conv_transpose1d = load_inline(
    name="conv_transpose1d",
    cpp_sources=conv_transpose1d_cpp_source,
    cuda_sources=conv_transpose1d_source,
    functions=["conv_transpose1d_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.has_bias = bias

        # Weight shape: (in_channels, out_channels, kernel_size)
        w = torch.randn(in_channels, out_channels, kernel_size)
        self.weight = nn.Parameter(w)
        if bias:
            b = torch.randn(out_channels)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.has_bias:
            return conv_transpose1d.conv_transpose1d_cuda(
                x,
                self.weight,
                self.bias,
                self.stride,
                self.padding,
                self.output_padding,
                self.groups,
                True
            )
        else:
            empty_bias = torch.tensor([], device=x.device, dtype=x.dtype)
            return conv_transpose1d.conv_transpose1d_cuda(
                x,
                self.weight,
                empty_bias,
                self.stride,
                self.padding,
                self.output_padding,
                self.groups,
                False
            )
